import{_ as t,a0 as p,w as o,s as d,ao as r,I as l,x as n,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"使用 Linux stat 命令創建靈活的文件列表 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux stat 命令創建靈活的文件列表 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux stat 命令創建靈活的文件列表 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux stat 命令創建靈活的文件列表 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200909 Using the Linux stat command to create flexible file listings","title":"使用 Linux stat 命令創建靈活的文件列表","tag":"202009","desc":""},"relativePath":"202009/20200909 Using the Linux stat command to create flexible file listings.md","filePath":"[post].md"}'),c={name:"202009/20200909 Using the Linux stat command to create flexible file listings.md"};function m(h,s,u,x,w,g){const a=p("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="使用-linux-stat-命令創建靈活的文件列表" tabindex="-1">使用 Linux stat 命令創建靈活的文件列表 <a class="header-anchor" href="#使用-linux-stat-命令創建靈活的文件列表" aria-label="Permalink to “使用 Linux stat 命令創建靈活的文件列表”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202009/21/223030wi3xfx2eprij13z2.jpg" alt=""></p><p><code>stat</code> 命令提供了很多關於文件的詳細信息。</p><p>它不僅提供了文件最近變化的日期/時間，還顯示了最近訪問文件的時間和權限變化。它可以同時告訴你文件的字節大小和塊的數量。它可以顯示文件使用的 inode 以及文件類型。它包括了文件所有者和相關用户組的名稱和 UID/GID。它以 “rwx”（被稱為 “人類可讀” 格式）和數字方式顯示文件權限。在某些系統中，它甚至可能包括文件創建的日期和時間（稱為“出生”）。</p><p>除了提供所有這些信息外，<code>stat</code> 命令還可以用來創建文件列表。這些列表非常靈活，你可以選擇包含上述任何或全部信息。</p><p>要生成一個自定義列表，你只需要使用 <code>stat</code> 命令的 <code>-c</code>（或 <code>--format</code>）選項，並指定你想要包含的字段。例如，要創建一個以兩種格式顯示文件權限的列表，使用這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stat -c &#39;%n %a %A&#39; my*</span></span>
<span class="line"><span>my.banner 664 -rw-rw-r--</span></span>
<span class="line"><span>mydir 775 drwxrwxr-x</span></span>
<span class="line"><span>myfile 664 -rw-rw-r--</span></span>
<span class="line"><span>myjunk 777 lrwxrwxrwx</span></span>
<span class="line"><span>mykey 664 -rw-rw-r--</span></span>
<span class="line"><span>mylog 664 -rw-rw-r--</span></span>
<span class="line"><span>myscript 755 -rwxr-xr-x</span></span>
<span class="line"><span>mytext 664 -rw-rw-r--</span></span>
<span class="line"><span>mytext.bak 664 -rw-rw-r--</span></span>
<span class="line"><span>mytwin 50 -rw-r-----</span></span>
<span class="line"><span>mywords 664 -rw-rw-r--</span></span></code></pre></div><p>如上例所示，<code>%n</code> 代表文件名，<code>%a</code> 代表八進制的權限，<code>%A</code> 代表 <code>rwx</code> 形式的權限。完整的列表如後面所示。</p><p>要為這個命令創建一個別名，輸入這個命令，或在 <code>.bashrc</code> 文件中添加這個定義。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias ls_perms=&quot;stat -c &#39;%n %a %A&#39;&quot;</span></span></code></pre></div><p>要創建一個非常接近 <code>ls -l</code> 提供的長列表，可以這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stat -c &#39;%A %h %U %G %s %y %n&#39; my*</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 255 2020-04-01 16:20:00.899374215 -0400 my.banner</span></span>
<span class="line"><span>drwxrwxr-x 2 shs shs 4096 2020-09-07 12:50:20.224470760 -0400 mydir</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 6 2020-05-16 11:12:00.460355387 -0400 myfile</span></span>
<span class="line"><span>lrwxrwxrwx 1 shs shs 11 2020-05-28 18:49:21.666792608 -0400 myjunk</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 655 2020-01-14 15:56:08.540540488 -0500 mykey</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 8 2020-03-04 17:13:21.406874246 -0500 mylog</span></span>
<span class="line"><span>-rwxr-xr-x 1 shs shs 201 2020-09-07 12:50:41.316745867 -0400 myscript</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 40 2019-06-06 08:54:09.538663323 -0400 mytext</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 24 2019-06-06 08:48:59.652712578 -0400 mytext.bak</span></span>
<span class="line"><span>-rw-r----- 2 shs shs 228 2019-04-12 19:37:12.790284604 -0400 mytwin</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 1983 2020-08-10 14:39:57.164842370 -0400 mywords</span></span></code></pre></div><p>不同之處包括： 1、不試圖將字段排成可辨認的一列，2、日期是 <code>yy-mm-dd</code> 格式，3、時間字段更精確，4、增加了時區（-0400 是 EDT）。</p><p>如果你想根據最後一次訪問的日期來列出文件（例如，用 <code>cat</code> 命令來顯示），使用這樣的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stat -c &#39;%n %x&#39; my* | sort -k2</span></span>
<span class="line"><span>mytwin 2019-04-22 11:25:20.656828964 -0400</span></span>
<span class="line"><span>mykey 2020-08-20 16:10:34.479324431 -0400</span></span>
<span class="line"><span>mylog 2020-08-20 16:10:34.527325066 -0400</span></span>
<span class="line"><span>myfile 2020-08-20 16:10:57.815632794 -0400</span></span>
<span class="line"><span>mytext.bak 2020-08-20 16:10:57.935634379 -0400</span></span>
<span class="line"><span>mytext 2020-08-20 16:15:42.323391985 -0400</span></span>
<span class="line"><span>mywords 2020-08-20 16:15:43.479407259 -0400</span></span>
<span class="line"><span>myjunk 2020-09-07 10:04:26.543980300 -0400</span></span>
<span class="line"><span>myscript 2020-09-07 12:50:41.312745815 -0400</span></span>
<span class="line"><span>my.banner 2020-09-07 13:22:38.105826116 -0400</span></span>
<span class="line"><span>mydir 2020-09-07 14:53:10.171867194 -0400</span></span></code></pre></div><p>用 <code>stat</code> 列出文件細節時，可用的選項包括：</p><ul><li><code>%a</code> - 八進制的訪問權限（注意 <code>#</code> 和 <code>0</code> 的 printf 標誌）</li><li><code>%A</code> – 人類可讀的訪問權限</li><li><code>%b</code> – 分配的塊數（見 <code>%B</code>）</li><li><code>%B</code> – <code>%b</code> 報告的每個塊的字節數</li><li><code>%C</code> – SELinux 安全上下文字符串</li><li><code>%d</code> – 十進制的設備編號</li><li><code>%D</code> – 十六進制的設備編號</li><li><code>%f</code> – 十六進制的原始模式</li><li><code>%F</code> – 文件類型</li><li><code>%g</code> – 所有者的組 ID</li><li><code>%G</code> – 所有者的組名</li><li><code>%h</code> – 硬鏈接的數量</li><li><code>%i</code> – inode 編號</li><li><code>%m</code> – 掛載點</li><li><code>%n</code> – 文件名</li><li><code>%N</code> – 如果是符號鏈接，會解引用為指向的文件名</li><li><code>%o</code> – 最佳 I/O 傳輸大小提示</li><li><code>%s</code> – 以字節為單位的總大小</li><li><code>%t</code> – 十六進制的主要設備類型，用於字符/塊設備特殊文件</li><li><code>%T</code> – 十六進制的次要設備類型，用於字符/塊設備特殊文件</li><li><code>%u</code> – 所有者的用户 ID</li><li><code>%U</code> – 所有者的用户名</li><li><code>%w</code> – 文件創建時間，以人類可讀形式； 如果未知，則為 <code>-</code>。</li><li><code>%W</code> – 文件創建時間，以 UNIX 紀元以來的秒數形式；如果未知，則為 <code>0</code>。</li><li><code>%x</code> – 上次訪問時間，以人類可讀形式</li><li><code>%X</code> – 上次訪問時間，以 UNIX 紀元以來的秒數形式</li><li><code>%y</code> – 上次數據修改時間，以人類可讀形式</li><li><code>%Y</code> – 上次數據修改時間，以 UNIX 紀元以來的秒數形式</li><li><code>%z</code> – 上次狀態改變的時間，以人類可讀形式</li><li><code>%Z</code> – 上次狀態改變的時間，以 UNIX 紀元以來的秒數形式</li></ul><p>這些字段的選擇都列在手冊頁中，你可以選擇任何一個，不過用你喜歡的選項創建一些別名應該可以省去很多麻煩。有些選項，如 SELinux 安全上下文字符串，除非在系統中有使用，它將不可用。文件創建時間只有在你的系統保留該信息的情況下才可用。</p><hr>`,19)),l("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"https://www.networkworld.com/article/3573802/using-the-linux-stat-command-to-create-flexible-file-listings.html"},{default:i(()=>[...s[0]||(s[0]=[n("https://www.networkworld.com/article/3573802/using-the-linux-stat-command-to-create-flexible-file-listings.html",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=n("作者：",-1)),e(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[n("geekpi",-1)])]),_:1}),s[9]||(s[9]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[n("Linux中國",-1)])]),_:1}),s[14]||(s[14]=n(" 榮譽推出",-1))])])}const b=t(c,[["render",m]]);export{f as __pageData,b as default};
